UNITS = [
 dict(id='A1-01',title='Pessoas, relações e trabalho',prerequisites=['FND-01','FND-03','FND-04'],
 goal='Apresentar duas pessoas, distinguir relação pessoal de profissão e corrigir uma informação num cadastro.',
 targets=['Be afirmativo, negativo e pergunta','Sujeito, objeto e posse'],
 support='neighbour = vizinho/a (neighbor também é aceito); partner = parceiro/a, com relação definida pelo contexto; parent = pai ou mãe; child = criança/filho; children = plural de child; teacher = professor/a; nurse = profissional de enfermagem; driver = motorista; job = emprego/função; work = trabalhar; live = morar; with = com; ready = pronto/a. He = ele; she = ela; they = eles/elas ou pessoa cujo gênero não se especifica; we = nós. Nos textos, os pronomes vêm explicitados.',
 explanation='I am / you are / he is / she is / we are / they are identificam ou descrevem. A negativa acrescenta not: She is not a driver → She isn’t a driver. A pergunta inverte: Is she a nurse? Não acrescentar do a estas perguntas. My, your, her, his e their identificam posse antes do nome: her job, their neighbour. Em She helps me, she faz a ação e me recebe a ajuda; my exige um nome depois. Helps = ajuda; her pode ser objeto em I help her ou posse em her job, conforme a posição.',
 readings=[('Dois perfis para a associação','My name is Lia. I’m a nurse. My neighbour is Ben. He is a driver. We are in Recife. Ben is not my partner. My partner is Jo. Jo is a teacher. We have one child. (Temos uma criança.)'),('Cartões do evento','Lia — nurse — neighbour: Ben\nBen — driver — neighbour: Lia\nJo — teacher — partner: Lia\nWelcome desk: Are you ready? (Vocês estão prontos?)\nLia and Ben: Yes, we are.')],
 audio='Host: Is Ben a teacher?\nLia: No, he isn’t. He is a driver. Jo is a teacher.\nHost: Is Jo your neighbour?\nLia: No. Jo is my partner. Ben is my neighbour.\nHost: And your job?\nLia: I’m a nurse.',
 questions=[('Qual é a profissão de Lia?','Nurse; profissional de enfermagem.'),('Ben é parceiro ou vizinho de Lia?','Vizinho.'),('Quem é professor/a?','Jo; o texto não define gênero de Jo.'),('A frase We are refere-se a quem na resposta do segundo texto?','Lia e Ben.'),('Na escuta, qual profissão foi atribuída incorretamente a Ben?','Teacher; Lia corrige para driver.'),('Na escuta, quem é parceiro de Lia?','Jo; não Ben.')],
 practice=[('Complete: I ___ a nurse.','am.'),('Complete: They ___ ready.','are.'),('Negue: Ben is a teacher.','Ben isn’t a teacher / Ben is not a teacher.'),('Transforme em pergunta: Jo is a teacher.','Is Jo a teacher?'),('Corrija: Do you are ready?','Are you ready? Be não usa do neste padrão.'),('Complete: Lia helps ___ (I/me/my).','me; pessoa que recebe ajuda.'),('Complete: She is Jo. This is ___ job (she/her).','her; antes de job.'),('Explique: My neighbour is a nurse. A palavra neighbour informa profissão?','Não; relação de vizinhança. Nurse informa profissão.')],
 guided='A recebe: Kim, teacher, neighbour Alex, partner Sol. B recebe: Alex, nurse, neighbour Kim. A apresenta Kim; B anota profissão e relações. B confirma “Is Sol your neighbour?”; A corrige. Troquem papéis para Alex. Use nomes fictícios; não é necessário revelar relações reais.',
 model='A: I’m Kim. I’m a teacher. Alex is my neighbour. Sol is my partner.\nB: Is Sol your neighbour?\nA: No. Sol is my partner.\nB: Is Alex a nurse?\nA: Yes.',
 transfer='Cartões novos: Eva, driver, neighbour Rui; Rui, teacher, neighbour Eva. Não há parceiro informado. Produza cadastro com profissão e relação e uma apresentação oral de cada pessoa. O parceiro confirma “Is Rui a driver?”; corrija. Depois explique em português quais informações não foram dadas.',
 evidence='Eva é driver; Rui é teacher; são vizinhos. Não inventar relacionamento amoroso. Correção possível: No. Rui is a teacher. Cadastro e destinatário devem recuperar profissão e relação de cada pessoa.',
 review='No início de A1-02, antes de reler, use Sol, nurse, neighbour Noa (driver). Apresente Sol e negue “Noa is a teacher”. Esperado: Sol is a nurse; Noa isn’t a teacher; Noa is a driver.',
 phon='Ouça I’m, he’s e she’s em exemplos de apresentação; reconstitua quem é a pessoa e sua profissão. Contração é opção, não obrigação. O nome deve continuar recuperável.',
 teacher='Brasileiros podem omitir be ou acrescentar do. Se houver isso, peça o contraste He is / Is he? antes de nova tentativa. Não inferir gênero por profissão. Parent não equivale a parente; neste vocabulário, significa pai ou mãe.'),
 dict(id='A1-02',title='Rotinas e uma hora para conversar',prerequisites=['A1-01','FND-06'],
 goal='Comparar duas rotinas e combinar uma conversa sem confundir acordar, levantar e começar o trabalho.',
 targets=['Presente simples afirmativo','Do/does e negação','Wh- e informação solicitada','Frequência e posição básica'],
 support='café = estabelecimento que serve bebidas/comida; library = biblioteca; afternoon = tarde; wake up = acordar; get up = levantar da cama; have breakfast = tomar café da manhã; start work = começar o trabalho; finish work = terminar o trabalho; usually = geralmente, não sempre; walk home = ir para casa a pé; every day = todos os dias; work at a café = trabalhar em um café; study = estudar; after = depois; before = antes; morning = manhã; evening = fim do dia/noite. Noon = meio-dia; p.m. indica período após meio-dia. Para os horários desta unidade: six = 6, seven = 7, eight = 8, nine = 9, four = 4, five = 5.',
 explanation='Rotinas usam a base verbal com I/you/we/they: I work. Com he/she, acrescenta-se -s ou -es; study vira studies: She studies. Perguntas usam Do you work? / Does she work?, com work na base. Negativas: I don’t work / She doesn’t work. Usually vem antes do verbo principal: I usually walk home. What time pede horário; Where pede lugar. Wake up pode ocorrer antes de get up; não são sinônimos exatos.',
 readings=[('Mensagem de Nina','I work at a café. I usually wake up at six in the morning, but I get up at seven. I have breakfast at seven. I start work at eight and finish at four in the afternoon. I usually walk home. I don’t work on Friday.'),('Agenda de Paulo','Paulo works at a library. He gets up at eight and has breakfast at nine. He starts work at ten and finishes at six in the evening. He studies English on Friday. He doesn’t work on Friday. He is free at noon. (Está disponível ao meio-dia.)')],
 audio='Paulo: Do you work on Friday, Nina?\nNina: No, I don’t. What time do you study English?\nPaulo: At nine in the morning. I’m free at noon.\nNina: A conversation at noon?\nPaulo: Yes. At the library?\nNina: Yes. Friday, at noon, at the library.',
 questions=[('Nina acorda e levanta no mesmo horário?','Não; acorda às 6h e levanta às 7h.'),('A que horas Nina termina o trabalho?','16h; four in the afternoon.'),('Paulo trabalha na sexta?','Não; estuda inglês.'),('Onde Paulo trabalha?','Na biblioteca.'),('Qual hora é combinada na escuta?','Meio-dia; a aula às 9h não é a conversa.'),('Qual é o lugar combinado?','Biblioteca, na sexta-feira.')],
 practice=[('Complete: Nina ___ at a café. (work)','works.'),('Complete: Paulo ___ English. (study)','studies.'),('Corrija: Does Nina works on Friday?','Does Nina work on Friday?'),('Negue: Paulo works on Friday.','Paulo doesn’t work on Friday.'),('Complete: ___ you get up at seven?','Do.'),('Pergunte o horário de início com What time.','What time do you start work? / What time does she start work?, conforme sujeito.'),('Ordene: usually / I / home / walk.','I usually walk home.'),('Uma pessoa wake up at six, get up at eight. Ela sai da cama às seis?','Não necessariamente; sai às oito no cenário.')],
 guided='A é Sam: trabalha segunda a quinta, 8h–16h; livre sexta às 10h. B é Eva: trabalha segunda a quinta, 9h–17h; aula sexta às 9h; livre sexta às 10h. Perguntem rotina, dia e hora livres e combinem conversa na sexta às 10h. Apoio: Monday to Thursday = segunda a quinta; free = disponível. Confirmem lugar: café.',
 model='A: Do you work on Friday?\nB: No, I don’t. I study at nine.\nA: Are you free at ten?\nB: Yes. At the café?\nA: Yes. Friday, at ten.',
 transfer='Novos cartões: Rui trabalha sexta 8h–12h e está livre às 14h; Sol trabalha sexta 9h–13h e está livre às 14h. Perguntem horários e combinem conversa às 14h na biblioteca. Registrem convite com dia, hora e lugar. Apoio: two in the afternoon = 14h; one in the afternoon = 13h.',
 evidence='Conversa sexta às 14h, biblioteca. Rui termina ao meio-dia; Sol às 13h. Não usar 10h copiado do modelo. O destinatário deve recuperar todos os dados, mesmo que a produção tenha pausas.',
 review='No início de A1-03, compare: Kim starts work at nine; Jo starts at ten. Pergunte a hora de cada um e negue “Kim starts at ten”. Respostas: What time does Kim/Jo start work? Kim doesn’t start at ten; Kim starts at nine.',
 phon='Escute starts e finishes em frases completas. O interlocutor deve recuperar sujeito e horário; permita repetir em blocos curtos. Não exigir velocidade de fala espontânea nesta prática inicial.',
 teacher='Separe erro de relógio do erro verbal. Mostre 16h = four in the afternoon antes das questões. A terceira pessoa em perguntas é marcada por does; não corrigir apenas pedindo para decorar s. Work é trabalhar/trabalho, job é um posto contável.'),
 dict(id='A1-03',title='Casa, bairro e o lugar de encontro',prerequisites=['A1-01','A1-02','FND-04'],
 goal='Ler uma descrição de moradia, localizar serviços num mapa simples e orientar alguém ao lugar combinado.',
 targets=['Existência com there is/are','Lugar e movimento básico','Artigos e referência básica'],
 support='flat = apartamento (apartment também é usado); rent = alugar, verbo neste uso; kitchen = cozinha; bedroom = quarto de dormir; bathroom = banheiro; library = biblioteca; bookshop = livraria (bookstore também é usado); bus stop = ponto de ônibus; next to = ao lado; opposite = em frente, no lado oposto; between = entre; near = perto; go to = ir a; street = rua; small = pequeno; bedroom não é toda espécie de room. A/B/C são endereços esquemáticos, não distâncias.',
 explanation='There is apresenta um elemento: There is a kitchen. There are apresenta vários: There are two bedrooms. Pergunte Is there a bathroom? / Are there two bedrooms? A/an introduz um exemplar; the retoma algo identificado: There is a library. The library is next to the café. Next to significa ao lado; opposite, no lado oposto. In/on/under indicam dentro/em cima/embaixo em relações físicas básicas. Go to the library indica destino; go home não usa to neste padrão.',
 readings=[('Anúncio fictício de moradia','We rent a small flat. There are two bedrooms. There is a kitchen and a bathroom. The kitchen is small. There is a table in the kitchen. A bag is under the table. The flat is near a bus stop. There isn’t a bookshop in the building. (Não há livraria no prédio.)'),('Mapa: vista de cima','Lado norte da rua: [A: Library] [B: Café] [C: Flat]\n================ STREET ================\nLado sul da rua: [D: Bookshop] [E: Bus stop] [F: Park]\nA fica em frente a D; B em frente a E; C em frente a F. Locais vizinhos na mesma linha ficam lado a lado.')],
 audio='Visitor: Is there a bookshop near the flat?\nHost: Yes. The bookshop is opposite the library.\nVisitor: At A?\nHost: No. A is the library. The bookshop is at D.\nVisitor: And our conversation?\nHost: At the café, B, next to the library.',
 questions=[('Quantos quartos de dormir há no apartamento?','Dois.'),('Onde está a bolsa?','Embaixo da mesa da cozinha.'),('Qual local está em frente à biblioteca?','Bookshop, D.'),('Qual local está ao lado do apartamento no mapa?','Café, B.'),('Na escuta, onde fica a livraria?','D; A é biblioteca.'),('Onde será a conversa?','Café B, ao lado da biblioteca; não na livraria.')],
 practice=[('Complete: There ___ two bedrooms.','are.'),('Complete: There ___ a bathroom.','is.'),('Pergunte se há uma cozinha.','Is there a kitchen?'),('Complete: There is a café. ___ café is small.','The; retoma o café apresentado.'),('No mapa, complete: The café is ___ the library.','next to.'),('No mapa, complete: The bookshop is ___ the library.','opposite.'),('Corrija: I go to home.','I go home.'),('Você quer comprar um livro. Escolha library/bookshop, explicando o sentido.','Bookshop é livraria; library é biblioteca. Não supor regras comerciais de toda biblioteca.')],
 guided='A vê o mapa, B recebe só nomes de lugares. B pergunta onde está a conversa; A informa café B, next to the library e opposite the bus stop. B posiciona o café numa grade vazia de seis espaços. Troquem papéis: agora encontro na livraria D, opposite the library. Apoio: Where is…? = onde fica…?',
 model='B: Where is the café?\nA: At B. Next to the library. Opposite the bus stop.\nB: B?\nA: Yes.\nB: Thank you.',
 transfer='Mapa novo: norte [A: Bookshop] [B: Flat] [C: Library]; sul [D: Café] [E: Park] [F: Bus stop]. Encontro na biblioteca C. Sem mostrar o mapa ao parceiro, informe local, letra e relação com o ponto de ônibus. Escreva bilhete e explique em português a diferença entre biblioteca e livraria para alguém que confundiu A e C.',
 evidence='Biblioteca C, opposite the bus stop F; livraria A. O bilhete deve levar à biblioteca, não ao café D do novo mapa nem à biblioteca A do mapa antigo.',
 review='No início de A1-04, desenhe library à esquerda de café, com bookshop em frente à library. Dê duas relações e uma frase com there is. Esperado: The library is next to the café; the bookshop is opposite the library; There is a bookshop (ou outro local do desenho).',
 phon='Escute LIBrary e BOOKshop e aponte os lugares antes de dar instruções. Repetição deve preservar o destino; não usar semelhança com “livraria” como pista suficiente.',
 teacher='Use mapa plano antes de exigir orientações no espaço real. Não incluir direita/esquerda produtivas como pré-requisito oculto. A pessoa pode indicar letra do mapa como estratégia de reparo.'),
 dict(id='A1-04',title='Comprar para uma refeição',prerequisites=['A1-02','A1-03','FND-05'],
 goal='Conferir o que há, perguntar quantidades e preços e escrever uma compra que respeite um orçamento.',
 targets=['Some, any e quantidade','How much e how many','Plurais frequentes e contabilidade'],
 support='meal = refeição; meat = carne, outra palavra; rice = arroz; egg = ovo; milk = leite; bread = pão; bottle = garrafa; bag = pacote neste cardápio; packet = pacote; need = precisar; have = ter; buy = comprar; price = preço, não prize (prêmio); cheap = barato; expensive = caro; total = total; six = seis. Valores em créditos fictícios. O tamanho das embalagens está fixado no anúncio; não é recomendação alimentar.',
 explanation='Egg é contável: one egg, six eggs. Rice e milk são apresentados como alimento/substância: some rice, some milk. Para contar embalagens: two bottles of milk. We have some rice afirma disponibilidade; We don’t have any eggs nega. Do we have any milk? pergunta. Some também aparece em ofertas e pedidos; não decorar “some nunca em pergunta”. How many eggs? pergunta número; How much milk? pergunta quantidade; How much is it? pergunta preço. A resposta ao preço não muda só porque o produto é contável.',
 readings=[('Lista antes da compra','We have some rice and four eggs. We don’t have any milk. We need six eggs for a meal. We need one bottle of milk. We don’t need bread. (Não precisamos de pão.) Our budget is eight credits. (Nosso orçamento é oito créditos.)'),('Preços por embalagem ou unidade','Rice: one bag — 5 credits\nEgg: one egg — 2 credits\nMilk: one bottle — 3 credits\nBread: one packet — 4 credits\nPrices are for this shop. (Preços desta loja.)')],
 audio='Shop assistant: How many eggs?\nCustomer: Two eggs, please. And one bottle of milk.\nShop assistant: Four eggs?\nCustomer: No. Two. We have four eggs at home.\nShop assistant: Two eggs and one bottle of milk. Seven credits.\nCustomer: Seven?\nShop assistant: Yes.',
 questions=[('Quantos ovos já existem em casa?','Quatro.'),('Quantos ovos faltam para chegar a seis?','Dois; distinguir cálculo da língua.'),('Há leite em casa?','Não.'),('Qual é o preço de uma garrafa de leite?','3 créditos.'),('Na escuta, qual quantidade é corrigida?','Four eggs é corrigido para two eggs.'),('Qual é o total confirmado?','7 créditos; dois ovos a 2 cada e leite a 3.')],
 practice=[('Complete: We don’t have ___ milk.','any.'),('Complete: We have ___ rice.','some.'),('Pergunte quantidade de ovos com How.','How many eggs?'),('Pergunte quantidade de leite com How.','How much milk?'),('Pergunte o preço de uma garrafa com How much.','How much is it? / How much is a bottle of milk?'),('Corrija: two bottle of milk.','two bottles of milk.'),('Escolha alimento arroz: some rice/three rices no contexto da lista.','some rice; para unidades usar embalagem especificada.'),('Budget 8, total 7. A compra cabe? Explique em português.','Sim; sobra 1. Cálculo não determina domínio de inglês.')],
 guided='A é comprador e vê a lista inicial; B é atendente e vê só preços. A pede dois ovos e uma garrafa de leite; B confirma incorretamente quatro ovos. A corrige e pergunta total. Depois B informa que bread custa 4; A explica We don’t need bread. Não adicione pão à conta.',
 model='A: Two eggs and one bottle of milk, please.\nB: Four eggs?\nA: No. Two eggs. How much is it?\nB: Seven credits.\nA: Thank you.',
 transfer='Nova lista: em casa há dois ovos e leite; são necessários quatro ovos e um pacote de pão. Preços novos: egg 1; bread packet 3; milk bottle 4. Orçamento 6. Escreva o que falta, faça o pedido e confirme preço. Diga em português por que o leite não entra na compra. Apoio: We have / We need / We don’t need.',
 evidence='Comprar dois ovos e um pacote de pão; total 5, dentro de 6. Não comprar leite, pois já há. O destinatário deve recuperar produto, quantidade e total; não copiar 7 do primeiro cenário.',
 review='No encontro posterior, antes de reler: há três ovos, são necessários cinco; ovos custam 2 cada; não há leite, uma garrafa custa 3. Pergunte quantidade e preço. Esperado: two eggs + one bottle of milk; total 7. Registrar cálculo e língua separadamente.',
 phon='Ouça egg/eggs e bottle/bottles com objetos ou desenhos. O interlocutor anota quantidade. Se o numeral permitir compreensão mas o plural não for audível, registre ambos os fatos.',
 teacher='Contabilidade depende do sentido e da embalagem. Não tratar two milks num café como impossível em qualquer contexto; aqui a lista pede garrafas. Cheap/expensive são avaliações contextuais: peça referência ao orçamento, sem impor julgamento econômico pessoal.')
]

UNITS += [
 dict(id='A1-05',title='O que acontece agora — reconhecer pessoas e objetos',prerequisites=['A1-01','A1-02','A1-03'],
 goal='Distinguir rotina de atividade atual e identificar objetos próximos ou distantes numa chamada de vídeo fictícia.',
 targets=['Presente contínuo','Rotina versus agora','Demonstrativos singular/plural','Adjetivos e intensificação básica'],
 support='now = agora; today = hoje; wait = esperar; study = estudar; cook = cozinhar; watch a film = assistir a um filme; rain = chover; cold = frio; blue = azul; red = vermelho; small = pequeno; large = grande; very = muito antes de adjetivo; this/these = este(s) perto; that/those = aquele(s) mais distante(s), conforme o ponto de vista do falante. Outside = do lado de fora; inside = do lado de dentro; home = casa/lar; wear = vestir/usar roupa; jacket = jaqueta.',
 explanation='Am/is/are + verbo com -ing apresenta ação em curso: I’m studying; She is cooking; They are waiting. Retire e final em make → making; study → studying; rain → raining. Para negar: They aren’t waiting. Para perguntar: Are they waiting? Simple apresenta rotina: I usually work at the café. Continuous apresenta situação atual: Today I’m working at home. Não aplicar -ing a qualquer verbo: I know the name, não I’m knowing the name neste sentido. This/that são singulares; these/those, plurais: These are my books. Adjetivos não recebem plural: two blue bags; The bags are very small.',
 readings=[('Mensagem de Jo para a equipe','I usually work at the café. Today I’m working at home. It’s raining and it’s cold. My neighbour Kim is in the kitchen. Kim is cooking. I’m not cooking. I’m studying English now. These are my books on the table. They are blue.'),('Quadro de uma chamada — ponto de vista de Jo','Perto de Jo: uma bolsa vermelha pequena e dois livros azuis.\nLonge de Jo, na mesma sala: duas bolsas vermelhas grandes.\nJo: This bag is small. These books are blue. Those bags are large.\nA descrição de perto/longe vale para Jo, não para quem lê esta página.')],
 audio='Caller: Are you working at the café, Jo?\nJo: No. I’m at home. I’m studying now.\nCaller: Is Kim studying too?\nJo: No. Kim is cooking.\nCaller: These blue books near you?\nJo: Yes. These are my books. Those red bags are not mine. (Aquelas bolsas vermelhas não são minhas.)',
 questions=[('Qual é a rotina de trabalho de Jo?','Geralmente trabalha no café.'),('O que Jo está fazendo agora?','Estudando inglês em casa.'),('Quem está cozinhando?','Kim.'),('Quais bolsas são grandes e distantes de Jo?','As duas vermelhas descritas com those.'),('Na escuta, Jo confirma que está no café?','Não; está em casa.'),('Os livros azuis perto de Jo são de Jo?','Sim; These are my books.')],
 practice=[('Complete: Kim ___ cooking.','is.'),('Negue: They are waiting.','They aren’t waiting / They are not waiting.'),('Pergunte: Jo is studying.','Is Jo studying?'),('Escolha: I usually work / am working at the café, para rotina habitual.','work.'),('Escolha: Now I study / am studying, para ação em curso neste cenário.','am studying.'),('Complete para dois livros próximos: ___ are my books.','These.'),('Corrija: two blues bags.','two blue bags.'),('Compare small e very small. Qual intensifica a descrição?','Very small; adjetivo small continua sem plural.')],
 guided='A desenha, do seu ponto de vista, uma bolsa pequena perto e dois livros grandes longe. B pergunta This bag? / Those books? e confirma cores: bolsa blue, livros red. Depois A representa Lia, que geralmente works at a library mas agora is waiting at a bus stop. B registra rotina e agora separadamente. Troquem papéis com Kim: geralmente studies at home, agora is cooking.',
 model='B: Are you working now?\nA: No. I usually work at a library. Now I’m waiting at the bus stop.\nB: This blue bag?\nA: Yes. This bag is small. Those books are large.',
 transfer='Novo cartão: Eva geralmente trabalha no café; agora estuda na biblioteca. Perto de Eva: dois livros vermelhos pequenos; longe: uma bolsa azul grande. Grave ou apresente a situação, faça etiquetas com demonstrativos e explique em português como rotina e agora diferem. O destinatário desenha os objetos nas posições informadas.',
 evidence='Eva usually works at a café; now she is studying at the library. These books are small/red; that bag is large/blue, do ponto de vista de Eva. Não usar those para uma única bolsa. O desenho do destinatário deve preservar número, cor e posição.',
 review='No início de A1-06: Jo usually cooks at home; now Jo is working at a café. Diga as duas situações; descreva duas bolsas azuis próximas. Esperado: Jo usually cooks at home. Now Jo is working at a café. These bags are blue.',
 phon='Destaque contraste de sentido: USUALLY e NOW, sem transformar todas as palavras em igual destaque. Em this/these, use o contexto de um/vários e confirmação pelo ouvinte; inteligibilidade não depende de imitar sotaque específico.',
 teacher='Se aluno omitir be em I studying, retome I am → I am studying. Não aceitar leitura de demonstrativos sem ponto de vista definido: mantenha os cartões de perto/longe junto ao personagem. Mine aparece somente com tradução no roteiro, sem avaliação produtiva.'),
 dict(id='A1-06',title='Convites, disponibilidade e regras de um encontro',prerequisites=['A1-04','A1-05'],
 goal='Convidar alguém, distinguir evento gratuito de pessoa disponível e combinar participação respeitando regras simples.',
 targets=['Can para capacidade e possibilidade','Imperativos e don’t','Pedidos e convites iniciais'],
 support='free = gratuito quando descreve preço; free = disponível quando descreve agenda; walk = caminhada/caminhar; go for a walk = fazer uma caminhada; meet = encontrar alguém combinado; invite = convidar; join us = juntar-se a nós; bring = trazer; take photos = fotografar; use = usar; door = porta; close = fechar; sorry = desculpe; tomorrow = amanhã; would like = gostaria; I’d like = I would like; can = poder/conseguir no contexto; can’t = não poder/não conseguir. Can you read the card? aqui pergunta capacidade de ler o cartão, não preço.',
 explanation='Can + verbo na base: I can come; She can read. Para negar: I can’t come. Para perguntar: Can you come? Não usar can to come. Can pode indicar capacidade ou possibilidade/disponibilidade: compare I can read English e I can come on Friday. Imperativo usa a base: Bring water. Negativo: Don’t take photos. Would you like to join us? faz convite; I’d like to join you aceita expressando desejo; Sorry, I can’t come recusa. I like walks descreve gosto, não o mesmo que aceitar este convite.',
 readings=[('Convite do centro comunitário','A walk on Friday at ten in the morning. Meet at the library. The event is free. Would you like to join us? Bring water. Don’t take photos inside the library. (Não fotografe dentro da biblioteca.) You can take photos in the park. (Pode fotografar no parque.)'),('Agenda e resposta de Eva','Eva: I work on Friday morning. I’m not free at ten. I’m free on Saturday. I can read the map in English. I’d like to join you on Saturday. Is there a walk on Saturday?\nOrganiser: Yes. Saturday at nine, at the library.')],
 audio='Organiser: Would you like to join us on Friday?\nEva: Sorry, I can’t come on Friday. I work in the morning.\nOrganiser: Are you free on Saturday at nine?\nEva: Yes. Is the event free?\nOrganiser: Yes. Bring water. Don’t take photos inside the library.\nEva: Saturday at nine. Thank you.',
 questions=[('O evento de sexta tem cobrança de participação no convite?','Não; free descreve preço gratuito.'),('Eva está disponível sexta às 10h?','Não; trabalha de manhã.'),('Qual capacidade Eva informa?','Ler o mapa em inglês.'),('Onde a regra permite fotos?','No parque; não dentro da biblioteca.'),('Qual dia e hora Eva aceita na escuta?','Sábado às 9h.'),('As duas perguntas com free na escuta perguntam a mesma coisa?','Não: disponibilidade de Eva e preço do evento.')],
 practice=[('Corrija: She can to read the map.','She can read the map.'),('Negue disponibilidade: I can come on Friday.','I can’t come on Friday.'),('Pergunte se a pessoa pode vir.','Can you come?'),('Proíba fotografar com take photos.','Don’t take photos.'),('Peça trazer água com bring.','Bring water / Bring water, please.'),('Convide com Would you like e join us.','Would you like to join us?'),('The event is free. Traduza free neste caso.','Gratuito; não informação sobre agenda.'),('I’m free on Saturday. Traduza free neste caso.','Disponível; não “eu sou gratuito”.')],
 guided='A organiza encontro gratuito sábado às 9h na biblioteca. B trabalha sábado de manhã, mas está livre às 14h. A também pode às 14h. A convida; B recusa a primeira hora e propõe 14h. Confirmem nova hora e regra Don’t take photos inside the library. Não alterar regras do evento para acomodar a agenda.',
 model='A: Would you like to join us on Saturday at nine?\nB: Sorry, I can’t come at nine. I’m free at two in the afternoon.\nA: I can come at two.\nB: Is the event free?\nA: Yes. Bring water.',
 transfer='Novo encontro gratuito: Sunday às 11h, biblioteca; regra Bring a pen e Don’t take photos. Kim está livre às 11h; Jo só às 15h. Faça convite a Kim e responda a Jo sem prometer nova sessão que não foi oferecida. Escreva confirmação para Kim e explique as regras em português. Apoio: Sunday = domingo; I’m sorry = sinto muito.',
 evidence='Kim confirma domingo 11h; Jo não pode participar do horário anunciado e não recebe uma sessão inventada às 15h. Levar caneta; não fotografar. Free é gratuito para o evento e disponível para Kim. Aceitar recusa cortês em bloco curto.',
 review='No início de A1-07: evento Saturday às 10h, custo 2 créditos; Lee está disponível. Explique por que Lee is free pode ser verdadeiro e The event is free é falso. Faça convite e recusa fictícia. Esperado: disponibilidade não é preço; Would you like to join us? / Sorry, I can’t come.',
 phon='Ao escutar can/can’t, não decida só por uma consoante isolada. Use o contexto e confirme “Friday?”; o parceiro devolve o dia em que pode participar. Se a negativa não for recuperável, reformule com I’m not free on Friday.',
 teacher='Não atribuir incapacidade geral a I can’t come on Friday: a restrição é de agenda. Distinguir a negativa da recusa educada; o aluno não precisa inventar motivo pessoal. Horários são de personagens.'),
 dict(id='A1-07',title='Contar o que aconteceu e explicar uma mudança',prerequisites=['A1-05','A1-06'],
 goal='Reconstruir um acontecimento curto, distinguir o plano do que ocorreu e explicar uma decisão com uma razão.',
 targets=['Was e were','Passado simples e did','And, but, because e so'],
 support='open = aberto; then = então/depois; yesterday = ontem; last Friday = sexta passada; last Saturday = sábado passado; was/were = passado de be; went = passado de go (ir); saw = passado de see (ver); had = passado de have; watched = assistiu; waited = esperou; stayed = ficou; arrived = chegou; closed = fechado; tired = cansado; because = porque/razão; so = por isso/resultado; but = mas/contraste; and = e/adição; later = depois; film = filme; meeting = encontro. Regular -ed não significa presente; horários nesta unidade são da manhã quando explicitados.',
 explanation='I/he/she/it was; you/we/they were situam estados passados. Negativas: wasn’t/weren’t. Perguntas: Was the library open? / Were you there? Verbos de ação têm forma passada em afirmação: We went; I watched. Com did/didn’t, usar base: Did you go? I didn’t go. Não usar Did you went. Because introduz razão: We stayed home because it was cold. So apresenta resultado: It was cold, so we stayed home. But contrasta; and adiciona. A relação precisa preservar o sentido, não só preencher um espaço.',
 readings=[('Plano e registro de sábado','Plan: Library, Saturday, nine in the morning.\nWhat happened: We went to the library at nine. The library was closed. It was cold. We waited for ten minutes. (Esperamos dez minutos.) Then we went to the café. Jo was there. We had tea and watched a short film. We didn’t take photos.'),('Mensagem para quem faltou','Hi, Eva. The meeting was at the café, not at the library. We went to the café because the library was closed. Jo was there, but Kim wasn’t. Kim stayed home. We watched a film and had tea. The film was short. (O filme foi curto.)')],
 audio='Eva: Were you at the library yesterday?\nLee: Yes, at nine. But it was closed.\nEva: Did you go home?\nLee: No, we didn’t. We went to the café.\nEva: Did you see Kim?\nLee: No. We saw Jo. Kim wasn’t there.\nEva: Did you watch a film?\nLee: Yes, we did.',
 questions=[('O plano inicial era encontrar-se onde?','Na biblioteca, sábado às 9h.'),('Por que foram ao café?','Porque a biblioteca estava fechada.'),('Kim estava no café?','Não; ficou em casa segundo a mensagem.'),('Quais duas atividades ocorreram no café?','Tomaram chá e assistiram a um filme.'),('Na escuta, Lee diz que foram para casa?','Não; foram ao café.'),('Quem Lee viu?','Jo; não Kim.')],
 practice=[('Complete: The library ___ closed.','was.'),('Complete: We ___ at the café.','were.'),('Negue: Kim was there.','Kim wasn’t there.'),('Corrija: Did you went home?','Did you go home?'),('Corrija: We didn’t watched a film.','We didn’t watch a film.'),('Complete com razão: We went to the café ___ the library was closed.','because.'),('Comece pela causa usando so: a biblioteca estava fechada; fomos ao café.','The library was closed, so we went to the café.'),('Escolha contraste: Jo was there ___ Kim wasn’t.','but.')],
 guided='A viu o ocorrido: Friday, library closed, went to café, saw Eva, had coffee, no film. B tem plano antigo: library, film with Kim. B pergunta Did you go to the library? / Did you see Kim? / Did you watch a film? A corrige os dados e explica a mudança. Depois B escreve mensagem de três frases com because ou so.',
 model='B: Did you see Kim?\nA: No. I saw Eva.\nB: Did you watch a film?\nA: No, I didn’t. The library was closed, so we went to the café. We had coffee.',
 transfer='Novo registro: domingo de manhã, parque fechado; grupo foi à biblioteca; Rui estava lá, Sol não; leram um livro curto e não assistiram a filme. Apoios: park = parque; read a book = leram um livro (grafia read no passado, pronúncia diferente); Sunday = domingo. Faça relato escrito e responda perguntas do parceiro sobre lugar, pessoa e atividade. Explique em português o motivo da mudança.',
 evidence='The park was closed, so we went to the library. Rui was there; Sol wasn’t. We read a short book. We didn’t watch a film. Aceitar frases curtas ligadas ou separadas. Não afirmar que fecharam a biblioteca; quem estava fechado era o parque.',
 review='No encontro de A1-08, antes de reler: café fechado; grupo foi ao parque; viu Kim; não tomou chá. Diga o que aconteceu e faça uma pergunta com did. Esperado: The café was closed, so we went to the park. We saw Kim. We didn’t have tea. Did you see Kim? (ou outra pergunta coerente).',
 phon='Compare watched e waited em áudio de apoio: não inserir a mesma sílaba extra em todo -ed. Priorize o ouvinte reconhecer a ação. Read no passado do apoio da transferência exige modelo sonoro; sem ele, registrar apenas leitura/escrita desse item.',
 teacher='Não ensinar did com was/were: Were you there? contrasta com Did you go? Se aluno inverter causa e resultado, desenhe dois cartões e reorganize. Não exigir a forma passada de read sem o apoio explicitado.'),
 dict(id='A1-08',title='Planejar uma visita e conferir o que levar',prerequisites=['A1-03','A1-06','A1-07'],
 goal='Combinar um plano futuro, distinguir destino de ação planejada e identificar os responsáveis por objetos.',
 targets=['Plano com going to','Posse com ’s'],
 support='tomorrow = amanhã; next Saturday = próximo sábado; visit = visitar; take = levar neste cenário; bring = trazer; map = mapa; lunch = almoço; parents = pais; shared = compartilhado; plan = plano; going to + verbo = plano de fazer algo; going to + lugar = ir a um destino. Jo’s bag = bolsa de Jo; my parents’ bag = bolsa dos meus pais. Aqui todos os objetos e planos são fictícios.',
 explanation='Be going to + verbo na base expressa plano: I’m going to visit Jo; We’re going to study. Pergunte Are you going to study? Negue We aren’t going to study. Não usar going to studying. Compare I’m going to the library: the library é destino, não verbo. Para posse, nome + ’s: Jo’s bag. Com plural regular terminado em s, apóstrofo após s: my parents’ bag. Se duas pessoas compartilham um objeto, Jo and Kim’s bag; se têm objetos separados, Jo’s bag and Kim’s bag. Jo’s também pode significar Jo is em Jo’s ready; o contexto resolve.',
 readings=[('Plano de visita','Next Saturday we’re going to visit Jo. Jo is in a flat near the library. We’re going to the library at ten in the morning. We’re going to read there. We aren’t going to buy books. Later, we’re going to have lunch at Jo’s flat. (Depois, vamos almoçar no apartamento de Jo.)'),('Lista de objetos e responsáveis','Kim’s bag: two books.\nRui’s bag: water and bread.\nJo and Kim’s map: one shared map.\nJo’s parents’ bag: three apples.\nKim is going to bring the map. Rui is going to bring water. Jo’s parents are going to bring the apples.')],
 audio='Jo: Are you going to bring the map, Rui?\nRui: No. Kim is going to bring the map. I’m going to bring water.\nJo: And the books?\nRui: They’re in Kim’s bag.\nJo: Are we going to buy books?\nRui: No. We’re going to read at the library.\nJo: At ten?\nRui: Yes, at ten in the morning.',
 questions=[('Quando será a visita?','Próximo sábado.'),('Going to the library informa destino ou ação verbal como study?','Destino: biblioteca.'),('O mapa é compartilhado por quem?','Jo e Kim.'),('De quem é a bolsa com maçãs?','Dos pais de Jo.'),('Na escuta, Rui vai levar o mapa?','Não; Kim vai levar. Rui leva água.'),('Vão comprar livros?','Não; vão ler na biblioteca às 10h da manhã.')],
 practice=[('Complete: She’s going to ___ Jo. (visit/visiting)','visit.'),('Pergunte o plano de trazer água.','Are you going to bring water?'),('Negue: We’re going to buy books.','We aren’t going to buy books.'),('Escreva a bolsa de Rui.','Rui’s bag.'),('Escreva a bolsa dos meus pais, usando parents.','My parents’ bag.'),('Escreva mapa compartilhado por Jo e Kim.','Jo and Kim’s map.'),('Compare Jo’s bag e Jo’s ready. O ’s tem a mesma função?','Não; posse em Jo’s bag; contração de is em Jo’s ready.'),('I’m going to the library. O trecho final é um verbo de ação?','Não; destino. Comparar I’m going to study, cujo verbo é study.')],
 guided='A recebe plano: Saturday 10h, library; vai levar water. B recebe plano: Saturday 10h, library; vai levar books e map compartilhado com A. Perguntem quem vai levar cada coisa e etiquetem bolsas separadas com nomes escolhidos. Confirmem que o mapa é compartilhado, não um mapa por pessoa.',
 model='A: Are you going to bring the map?\nB: Yes. I’m going to bring our map. (Nosso mapa.)\nA: I’m going to bring water.\nB: The books are in Kim’s bag.\nA: Saturday at ten, at the library.',
 transfer='Plano novo: Sunday às 11h, parque; Lia leva água; Ben leva duas maçãs; o mapa pertence a Lia e Ben juntos. Eles vão caminhar, não estudar. Escreva confirmação com dia, hora, destino, ação e responsáveis. Faça perguntas ao parceiro e explique em português a quem pertence cada objeto. Apoio: Sunday = domingo; walk = caminhar; eleven = onze.',
 evidence='Sunday, 11h, park; They’re going to walk; They aren’t going to study; Lia is going to bring water; Ben is going to bring two apples; Lia and Ben’s map. Não trocar propriedade pelo responsável por transportar: o mapa compartilhado pode ser carregado por um deles.',
 review='Na sessão posterior, planeje Monday às 9h na biblioteca: Sol leva livro; Kim leva chá; mapa pertence só a Kim. Escreva plano de ler e compare Kim’s map com Kim’s ready. Esperado: We’re going to read; Kim’s map = posse; Kim’s ready = Kim is ready. Esta revisão deve preceder a avaliação integrada A1.',
 phon='Escute going to em fala clara e mantenha os dados de plano reconhecíveis. Não exigir gonna nem considerar redução informal requisito de domínio. Em posse, faça o destinatário identificar de quem é o objeto, permitindo confirmação.',
 teacher='A forma ’s exige relação clara. Não classificar todo ’s como posse; contraste o nome que vem depois e o predicado ready. Se o foco futuro estiver pesado, separar encontro de planos e encontro de posse antes da tarefa conjunta.')
]

# Keep retrieval prompts separate from the answer key in student-facing materials.
for unit in UNITS:
    separator = ' Esperado: ' if ' Esperado: ' in unit['review'] else ' Respostas: '
    unit['review'], unit['review_answer'] = unit['review'].split(separator, 1)
